import{_ as n,c as i,o as a,ah as t}from"./chunks/framework.oAolcYhj.js";const r="/Qonnectra-docs/pr-14/images/manual/teil-a/login_start.jpg",s="/Qonnectra-docs/pr-14/images/manual/teil-a/login_start_detail.jpg",l="/Qonnectra-docs/pr-14/images/manual/teil-a/login_navigation.jpg",d="/Qonnectra-docs/pr-14/images/manual/teil-a/login_sidebar.jpg",o="/Qonnectra-docs/pr-14/images/manual/teil-a/login_header.jpg",u="/Qonnectra-docs/pr-14/images/manual/teil-a/login_settings.jpg",z=JSON.parse('{"title":"3. Einstieg und Anmeldung","description":"","frontmatter":{},"headers":[],"relativePath":"manual/teil-a-anwenderhandbuch/03-einstieg-und-anmeldung.md","filePath":"manual/teil-a-anwenderhandbuch/03-einstieg-und-anmeldung.md"}'),h={name:"manual/teil-a-anwenderhandbuch/03-einstieg-und-anmeldung.md"};function g(m,e,c,b,p,k){return a(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="_3-einstieg-und-anmeldung" tabindex="-1">3. Einstieg und Anmeldung <a class="header-anchor" href="#_3-einstieg-und-anmeldung" aria-label="Permalink to &quot;3. Einstieg und Anmeldung&quot;">​</a></h1><h2 id="_3-1-zugang-zur-anwendung" tabindex="-1">3.1 Zugang zur Anwendung <a class="header-anchor" href="#_3-1-zugang-zur-anwendung" aria-label="Permalink to &quot;3.1 Zugang zur Anwendung&quot;">​</a></h2><p>Qonnectra wird über einen Webbrowser bedient; eine Installation auf Ihrem Rechner ist nicht nötig. Die Adresse zur Anmeldung erhalten Sie von Ihrer Organisation oder zuständigen Verwaltung. Auf der Anmeldeseite geben Sie unter der Überschrift „Anmelden“ Ihre Zugangsdaten in die Felder „Benutzername“ und „Passwort“ ein. Mit einem Klick auf „Login“ – oder mit der Eingabetaste – melden Sie sich an und gelangen zum Dashboard.</p><p class="img-row"><img src="'+r+'" alt="Screenshot Anmeldeseite mit dem Anmeldeformular auf der rechten Seite" data-zoomable="true"><img src="'+s+'" alt="Screenshot Ausschnittvergrößerung des Anmeldeformulars mit den Feldern „Benutzername“ und „Passwort“ und der Schaltfläche „Login“" data-zoomable="true"></p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Stimmen Benutzername oder Passwort nicht, erscheint am unteren Bildschirmrand kurz die Meldung „Fehler beim Anmelden“ und Sie bleiben auf der Anmeldeseite. Prüfen Sie in diesem Fall die Groß- und Kleinschreibung.</p></div><h3 id="_3-1-1-noch-keine-zugangsdaten" tabindex="-1">3.1.1 Noch keine Zugangsdaten? <a class="header-anchor" href="#_3-1-1-noch-keine-zugangsdaten" aria-label="Permalink to &quot;3.1.1 Noch keine Zugangsdaten?&quot;">​</a></h3><p>Falls Sie noch keine Zugangsdaten erhalten haben, wenden Sie sich bitte an Ihre Projektleitung oder Ihre Administration. Ein Benutzerkonto kann dort für Sie angelegt werden.</p><h3 id="_3-1-2-passwort-vergessen" tabindex="-1">3.1.2 Passwort vergessen? <a class="header-anchor" href="#_3-1-2-passwort-vergessen" aria-label="Permalink to &quot;3.1.2 Passwort vergessen?&quot;">​</a></h3><p>Derzeit gibt es keine „Passwort vergessen“-Funktion im System. Wenn Sie Ihr Passwort nicht mehr wissen, hilft Ihnen Ihre Projektleitung oder Administration weiter. Dort kann das Passwort zurückgesetzt oder ein neues vergeben werden.</p><h2 id="_3-2-navigation-in-der-anwendung" tabindex="-1">3.2 Navigation in der Anwendung <a class="header-anchor" href="#_3-2-navigation-in-der-anwendung" aria-label="Permalink to &quot;3.2 Navigation in der Anwendung&quot;">​</a></h2><p>Nach der Anmeldung befinden Sie sich auf dem Dashboard. Die Bedienoberfläche ist immer gleich aufgebaut und besteht aus drei Bereichen: der <strong>Navigationsleiste</strong> am linken Rand, der <strong>Kopfzeile</strong> am oberen Rand und der <strong>Inhaltsfläche</strong> in der Mitte.</p><p><img src="'+l+'" alt="Screenshot Startbildschirm mit Hervorhebung der einzelnen Bestandteile der App" class="big no-border" data-zoomable="true"></p><h3 id="_3-2-1-navigationsleiste" tabindex="-1">3.2.1 Navigationsleiste <a class="header-anchor" href="#_3-2-1-navigationsleiste" aria-label="Permalink to &quot;3.2.1 Navigationsleiste&quot;">​</a></h3><p>Über die Navigationsleiste am linken Rand wechseln Sie zu allen verfügbaren Ansichten. Sie bleibt beim Arbeiten immer sichtbar, der aktive Eintrag ist farbig hervorgehoben. Die Einträge sind nach Themen gruppiert:</p><ul><li>„Info“ – „Dashboard“ (Startansicht mit Gesamtüberblick, siehe Kapitel <a href="./04-dashboard.html">Dashboard</a>) und „Karte“ (Netzinfrastruktur auf der Karte, siehe Kapitel <a href="./05-karte.html">Karte</a>)</li><li>„Funktionen“ – „Störungsanalyse“, „Nachverdichtung“, „Leitungsauskunft“ und „Wertermittlung“: Auswertungen und Verfahren, die auf den dokumentierten Daten aufbauen</li><li>„Rohr“ – „Verwaltung“ (Anlegen und Verwalten von Rohren, siehe Kapitel <a href="./06-rohrverwaltung.html">Rohrverwaltung</a>), „Zuordnung“ (Zuordnung der Rohre zu den Trassen, siehe Kapitel <a href="./07-rohrzuordnung.html">Rohrzuordnung</a>), „Verzweigung“ und „Mikrorohre“</li><li>„Kabel“ – „Netzschema“ und „Faserweg“</li><li>„Gebäude“ – „Adressen“</li><li>„System“ – „Logs“ und „Einstellungen“ (siehe Abschnitt 3.2.4)</li></ul><p><img src="'+d+'" alt="Screenshot Dashboard mit Hervorhebung der Navigationsleiste am linken Rand" data-zoomable="true"></p><p>Ein Klick auf einen Gruppennamen – etwa „Funktionen“ – klappt die Gruppe zu und wieder auf. Einträge, die Sie nicht benötigen, können Sie dauerhaft ausblenden:</p><ol><li>Klicken Sie oben rechts neben dem Schriftzug „Qonnectra“ auf das Symbol mit den Schiebereglern („Seitenleiste anpassen“).</li><li>Klicken Sie neben einem Eintrag auf „Ausblenden“. Ausgeblendete Einträge bleiben in diesem Modus blass sichtbar und lassen sich über „Einblenden“ zurückholen; „Seitenleiste zurücksetzen“ stellt alle Einträge und Gruppen wieder her.</li><li>Beenden Sie die Anpassung über dasselbe Symbol („Fertig“).</li></ol><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Zugeklappte Gruppen und ausgeblendete Einträge merkt sich nur der Browser, in dem Sie sie eingestellt haben – an einem anderen Rechner sehen Sie wieder die vollständige Navigationsleiste. Welche Einträge überhaupt erscheinen, hängt zudem von Ihren Rechten ab: Fehlt ein hier genannter Eintrag, wenden Sie sich an Ihre Administration.</p></div><h3 id="_3-2-2-kopfzeile" tabindex="-1">3.2.2 Kopfzeile <a class="header-anchor" href="#_3-2-2-kopfzeile" aria-label="Permalink to &quot;3.2.2 Kopfzeile&quot;">​</a></h3><p>Oben links in der Anwendung befindet sich das Projektauswahl-Menü. Hier wählen Sie das Projekt aus, mit dem Sie aktuell arbeiten möchten; bei einem Wechsel aktualisieren sich alle angezeigten Inhalte automatisch. In den Kartenansichten steht daneben zusätzlich die Schaltfläche „Alle Projekte anzeigen“, mit der Sie die Beschränkung auf das gewählte Projekt vorübergehend aufheben.</p><p>Oben rechts in der Kopfzeile finden Sie:</p><ul><li>die aktuelle Softwareversion, z. B. „v1.7.0“ – geben Sie diese Angabe mit an, wenn Sie einen Fehler bei Ihrem Systemadministrator melden</li><li>die Spracheinstellung: Deutsch („DE“) oder Englisch („EN“)</li><li>einen Verweis auf das Projekt bei GitHub, in dem Qonnectra entwickelt wird</li><li>„Hell-/Dunkelmodus umschalten“</li><li>„Abmelden“ – danach werden Sie automatisch zur Anmeldeseite zurückgeleitet</li></ul><p><img src="'+o+'" alt="Screenshot Dashboard mit Hervorhebung der Kopfzeile am oberen Rand" data-zoomable="true"></p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Wenn Ihre Installation eine Adresse für dieses Handbuch hinterlegt hat, erscheint zusätzlich ein Buchsymbol („Dokumentation“), das das Handbuch in einem neuen Tab öffnet.</p></div><h3 id="_3-2-3-inhalt" tabindex="-1">3.2.3 Inhalt <a class="header-anchor" href="#_3-2-3-inhalt" aria-label="Permalink to &quot;3.2.3 Inhalt&quot;">​</a></h3><p>In der zentralen Inhaltsfläche werden alle projektbezogenen Informationen angezeigt: Statistiken, Listen, Karten usw. Welche Inhalte sichtbar sind, hängt vom gewählten Projekt (oben links in der Kopfzeile), dem gewählten Navigationseintrag (linke Navigationsleiste) und ggf. von dem gewählten Reiter (meist unterhalb der Kopfzeile) ab.</p><p>Karten, Grafiken und Listen sind meist interaktiv: Beispielsweise können Sie in einem Diagramm mit der Maus über einen Datenpunkt fahren („hovern“), um Details anzuzeigen.</p><h3 id="_3-2-4-einstellungen" tabindex="-1">3.2.4 Einstellungen <a class="header-anchor" href="#_3-2-4-einstellungen" aria-label="Permalink to &quot;3.2.4 Einstellungen&quot;">​</a></h3><p>Ganz unten links, in der Gruppe „System“, finden Sie den Eintrag „Einstellungen“. Hier können individuelle Einstellungen vorgenommen werden, z. B. zu Ihrem Benutzerkonto, zur Darstellung der Karte oder zur Breite der Navigationsleiste („Erweitert“ mit Beschriftungen oder „Eingeklappt“ nur mit Symbolen). Darüber steht der Eintrag „Logs“ mit den Systemprotokollen; er ist nur mit den entsprechenden Rechten sichtbar.</p><p><img src="'+u+'" alt="Screenshot Dashboard mit Hervorhebung der Gruppe „System“ mit „Logs“ und „Einstellungen“ unten links" data-zoomable="true"></p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Wenn die Gruppe „System“ nicht zu sehen ist, scrollen Sie in der Navigationsleiste nach unten.</p></div>',32)])])}const w=n(h,[["render",g]]);export{z as __pageData,w as default};
